27	class ResumeDriver
28	{
29	public:
30	  // data0/data1/abstractcs/command are defined once in abstract_command.hpp;
31	  // dmcontrol/dmstatus are run-control registers specific to this driver.
32	  static constexpr uint8_t kData0      = kDmiData0;
33	  static constexpr uint8_t kData1      = kDmiData1;
34	  static constexpr uint8_t kDmcontrol  = 0x10;
35	  static constexpr uint8_t kDmstatus   = 0x11;
36	  static constexpr uint8_t kAbstractcs = kDmiAbstractcs;
37	  static constexpr uint8_t kCommand    = kDmiCommand;
38	
39	  static constexpr uint16_t kCsrDpc      = 0x7B1;
40	  static constexpr uint16_t kCsrDcsr     = 0x7B0;
41	  static constexpr uint16_t kCsrPmpcfg0  = 0x3A0;
42	  static constexpr uint16_t kCsrPmpaddr0 = 0x3B0;
43	  static constexpr uint16_t kCsrFcsr     = 0x003;
44	  static constexpr uint16_t kCsrMstatus  = 0x300;
45	  static constexpr uint16_t kCsrMisa     = 0x301;
46	  static constexpr uint16_t kCsrMedeleg  = 0x302;
47	  static constexpr uint16_t kCsrMideleg  = 0x303;
48	  static constexpr uint16_t kCsrMie      = 0x304;
49	  static constexpr uint16_t kCsrMtvec    = 0x305;
50	  static constexpr uint16_t kCsrMscratch = 0x340;
51	  static constexpr uint16_t kCsrMepc     = 0x341;
52	  static constexpr uint16_t kCsrMcause   = 0x342;
53	  static constexpr uint16_t kCsrMtval    = 0x343;
54	  static constexpr uint16_t kCsrMip      = 0x344;
55	  static constexpr uint16_t kCsrSatp     = 0x180;
56	  static constexpr uint16_t kCsrMcycle   = 0xB00;
57	  static constexpr uint16_t kCsrMinstret = 0xB02;
58	  // Andes machine setup CSRs crt0 writes at boot (see hybrid_state_v1):
59	  // mcache_ctl enables the L1 I/D caches, mmisc_ctl holds misc machine config.
60	  static constexpr uint16_t kCsrMcacheCtl = 0x7CA;
61	  static constexpr uint16_t kCsrMmiscCtl  = 0x7D0;
62	  static constexpr uint16_t kCsrVlenb    = 0xC22;
63	  static constexpr uint16_t kCsrVstart   = 0x008;
64	  static constexpr uint16_t kCsrVxsat    = 0x009;
65	  static constexpr uint16_t kCsrVxrm     = 0x00A;
66	  static constexpr uint16_t kCsrVcsr     = 0x00F;
67	  static constexpr uint16_t kCsrVtype    = 0xC21;
68	  static constexpr uint16_t kCsrVl       = 0xC20;
69	
70	  static constexpr uint32_t kDmcontrolDmactive  = 1u << 0;
71	  static constexpr uint32_t kDmcontrolResumereq = 1u << 30;
72	  static constexpr uint32_t kDmcontrolHaltreq   = 1u << 31;
73	
74	  static constexpr uint32_t kDmstatusAllhalted    = 1u << 9;
75	  static constexpr uint32_t kDmstatusAllresumeack = 1u << 17;
76	
77	  static constexpr uint32_t kAbstractcsBusy        = hybrid::kAbstractcsBusy;
78	  static constexpr uint32_t kAbstractcsCmderrMask  = hybrid::kAbstractcsCmderrMask;
79	
80	  // mstatus extension-state fields: FS (bits 14:13), VS (bits 10:9).
81	  // "Initial" (01) is the minimal enable the abstract FPR / V writes require.
82	  static constexpr uint64_t kMstatusFsMask    = 0x6000ULL;
83	  static constexpr uint64_t kMstatusFsInitial = 0x2000ULL;
84	  static constexpr uint64_t kMstatusVsMask    = 0x600ULL;
85	  static constexpr uint64_t kMstatusVsInitial = 0x200ULL;
86	
87	  static constexpr unsigned kPollIterations = kDmiPollIterations;
88	
89	  // scratch_gpa: the GUEST address of the V-register transport page (L26:
90	  // v_scratch_gpa(ram_base, ram_size) = the mmap's top page). Defaults to the
91	  // "unset" sentinel; a non-V resume never reads it, but a V resume with the
92	  // GPA still unset throws in the sweep (no silent transport via a bogus
93	  // address). The simulator passes the real value from platform.main_memory.
94	  explicit ResumeDriver(DmiBus& bus, uint64_t scratch_gpa = kVScratchGpaUnset)
95	      : bus_{bus}, scratch_gpa_{scratch_gpa}
96	  {}
97	
98	  void resume(const hybrid_state_v1& state)
99	  {
100	    if (state.magic != HYBRID_STATE_MAGIC)
101	      throw std::runtime_error("ResumeDriver::resume: bad magic");
102	    if (state.version != HYBRID_STATE_VERSION)
103	      throw std::runtime_error("ResumeDriver::resume: unsupported version");
104	    // L6: only U(0)/S(1)/M(3) fit dcsr.prv; 2 is the reserved encoding.
105	    if (state.priv == 2 || state.priv > 3)
106	      throw std::runtime_error("ResumeDriver::resume: invalid privilege");
107	
108	    // dmactive must transition 0->1 in its own write before any other
109	    // DMCONTROL bit is honored (RISC-V Debug Spec).
110	    bus_.write(kDmcontrol, kDmcontrolDmactive);
111	    request_halt();
112	    poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");
113	
114	    // mstatus: enable FS / VS so the following FPR / V abstract writes are
115	    // accepted (FS or VS == Off disables the extension and the hart NACKs
116	    // the writes). The drained state.mstatus may legitimately carry FS or
117	    // VS at Off (e.g. an OS context-switched the regs away before the
118	    // trigger fired) -- gating the write on the drained field skips the
119	    // enable and silently NACKs every subsequent FPR / V-CSR write. Always
120	    // write mstatus when either extension is in scope; force-OR Initial
121	    // when the drained field is Off. This enable is local to the vsim
122	    // phase; the state.mstatus written to the handoff file is left
123	    // unmodified.
124	    if (state.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
125	      uint64_t enable_mstatus = state.mstatus;
126	      if ((state.flags & HYBRID_FLAG_FP) && (enable_mstatus & kMstatusFsMask) == 0)
127	        enable_mstatus |= kMstatusFsInitial;  // FS = Initial
128	      if ((state.flags & HYBRID_FLAG_V)  && (enable_mstatus & kMstatusVsMask) == 0)
129	        enable_mstatus |= kMstatusVsInitial;  // VS = Initial
130	      write_csr_abstract_or_pb(kCsrMstatus, enable_mstatus);
131	    }
132	
133	    // FPR restore (requires mstatus.FS enabled above).
134	    if (state.flags & HYBRID_FLAG_FP) {
135	      for (uint16_t i = 0; i < 32; ++i)
136	        write_64bit_register(regno_fpr(i), state.fpr[i]);
137	      // L20: fcsr (frm + sticky fflags). Same FS gate as the FPRs; PB
138	      // fallback scratch x5 is overwritten by the GPR loop below.
139	      write_csr_abstract_or_pb(kCsrFcsr, state.fcsr);
140	    }
141	
142	    // Tier-A V CSR restore (before GPRs: PB fallback uses x5 as scratch;
143	    // the GPR loop overwrites x5 afterward so state is preserved).
144	    if (state.flags & HYBRID_FLAG_V) {
145	      // V data regfile: reload v0..v31 from the shared scratch region via the
146	      // Program Buffer. Runs BEFORE the architectural V-CSR restore below
147	      // because the sweep's own vsetvl (e8/m1) clobbers vtype/vl/vstart, which
148	      // the restore then overwrites with the architectural values. The sweep
149	      // uses x5/x6/x7 as scratch (x7 is the base pointer); the GPR loop below
150	      // restores all three. The wire format reserves HYBRID_VLEN_BYTES_MAX per
151	      // register, so that -- not the runtime vlenb -- is the scratch stride.
152	      if (scratch_gpa_ == kVScratchGpaUnset)
153	        throw std::runtime_error(
154	          "ResumeDriver::resume: V state present but scratch GPA unset");
155	      pb_v_data_sweep(bus_, scratch_gpa_, HYBRID_VLEN_BYTES_MAX, state.vlenb,
156	                      /*load=*/true);
157	
158	      // Tier-B: vtype+vl via vsetvl x0,x5,x6 in PB.
159	      // Direct csrrw to vtype sets vill; vl is read-only. Stage operands in
160	      // scratch GPRs x5(vl) and x6(vtype) then let vsetvl set both atomically.
161	      // x5/x6 are overwritten by the GPR loop below, so no leakage.
162	      write_64bit_register(regno_gpr(5), state.vl);
163	      write_64bit_register(regno_gpr(6), state.vtype);
164	      const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
165	      exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
166	      // vstart must come AFTER vsetvl: vsetvl resets vstart to 0.
167	      write_csr_abstract_or_pb(kCsrVstart, state.vstart);
168	      write_csr_abstract_or_pb(kCsrVxsat,  state.vxsat);
169	      write_csr_abstract_or_pb(kCsrVxrm,   state.vxrm);
170	      write_csr_abstract_or_pb(kCsrVcsr,   state.vcsr);
171	    }
172	
173	    // L6: dret resumes into dcsr.prv, which is M after the boot halt. For an
174	    // S/U-mode handoff, read-modify-write the prv field so the ROI executes
175	    // in the drained privilege; M-mode states skip the write (prv already 3).
176	    // Before the GPR loop: a PB fallback would clobber scratch x5.
177	    if (state.priv != 3) {
178	      const uint64_t dcsr =
179	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr");
180	      write_csr_abstract_or_pb(kCsrDcsr,
181	                               (dcsr & ~uint64_t{0x3}) | state.priv);
182	      // An M-only core WARL-pins dcsr.prv to 3; resuming anyway would
183	      // silently measure the ROI in the wrong privilege. Verify and abort.
184	      const uint64_t got =
185	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr verify")
186	        & 0x3u;
187	      if (got != state.priv)
188	        throw std::runtime_error(
189	          "ResumeDriver::resume: engine does not implement privilege level "
190	          + std::to_string(state.priv)
191	          + " (dcsr.prv pinned to " + std::to_string(got)
192	          + "); pick an S/U-capable engine");
193	    }
194	
195	    // GPRs + DPC (after V CSRs so PB scratch x5 is safe to overwrite).
196	    for (uint16_t i = 1; i < 32; ++i)
197	      write_64bit_register(regno_gpr(i), state.gpr[i]);
198	    write_64bit_register(regno_csr(kCsrDpc), state.pc);
199	
200	    // L2: mirror the producer's PMP block into the cycle engine for EVERY
201	    // privilege level. An S/U ROI cannot fetch without it (PMP implemented +
202	    // no matching entry faults every S/U access, priv spec v1.10); an M-mode
203	    // ROI bypasses *unlocked* entries but is still bound by *locked* ones, so
204	    // mirroring keeps a producer-locked region enforced inside the window
205	    // instead of silently vanishing. All pmpaddr before any pmpcfg (a locked
206	    // cfg discards later addr writes to that entry); odd pmpcfg CSRs do not
207	    // exist on RV64. Tolerant writes: entries beyond what the hart implements
208	    // mirror as no-ops, and an all-zero block (no PMP configured) writes the
209	    // reset value harmlessly. write_csr_tolerant takes no PB-fallback scratch
210	    // GPR, so running this after the GPR loop is safe.
211	    for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
212	      write_csr_tolerant(kCsrPmpaddr0 + i, state.pmpaddr[i]);
213	    for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
214	      write_csr_tolerant(kCsrPmpcfg0 + i, state.pmpcfg[i]);
215	
216	    write_csr_tolerant(kCsrMtvec, state.mtvec);
217	
218	    // L23: mscratch is the M-mode software scratch CSR -- a pure read/write
219	    // register with no hardware side effects, legal to use inside a trap-free
220	    // ROI. Restore it so a value stashed before the handoff survives into the
221	    // vsim phase.
222	    write_csr_tolerant(kCsrMscratch, state.mscratch);
223	
224	    // L24: the writable M-mode trap/interrupt CSRs. In the trap-free,
225	    // interrupt-free ROI envelope these are ordinary read/write registers, so a
226	    // value stashed before the handoff must survive into the vsim phase (same
227	    // round-trip as mscratch). Tolerant writes: a WARL / read-only field (mip's
228	    // hardware-driven pending bits, or mtval on a core that hardwires it)
229	    // mirrors as a no-op. medeleg/mideleg/satp stay unrestored -- they are
230	    // S-mode CSRs the M-only default engine does not implement (L3/L4).
231	    write_csr_tolerant(kCsrMepc,   state.mepc);
232	    write_csr_tolerant(kCsrMcause, state.mcause);
233	    write_csr_tolerant(kCsrMtval,  state.mtval);
234	    write_csr_tolerant(kCsrMie,    state.mie);
235	    write_csr_tolerant(kCsrMip,    state.mip);
236	
237	    // Andes cache fix: restore the machine setup CSRs crt0 wrote at boot. The
238	    // functional engine ran crt0 (where `csrw mcache_ctl` enables the L1 I/D
239	    // caches) but has no cache model, so without this the cycle engine resumes
240	    // at the ROI with caches at their reset default -- DISABLED -- and the
241	    // whole measured window runs uncached, inflating it severalfold. Tolerant
242	    // writes: an engine without these custom CSRs (e.g. non-Andes) mirrors the
243	    // write as a no-op, and a drained 0 (caches were off) restores the reset
244	    // state, so this is always safe to issue.
245	    write_csr_tolerant(kCsrMcacheCtl, state.mcache_ctl);
246	    write_csr_tolerant(kCsrMmiscCtl,  state.mmisc_ctl);
247	
248	    // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
249	    // from QEMU1's drain value. Without this, vsim's local counter starts
250	    // at zero, so the drained mcycle delta (vsim minus QEMU 1) would no
251	    // longer measure the ROI. PB fallback uses x5 as scratch; safe to
252	    // overwrite here as the GPR loop already ran.
253	    write_csr_abstract_or_pb(kCsrMcycle,   state.mcycle);
254	    write_csr_abstract_or_pb(kCsrMinstret, state.minstret);
255	
256	    clear_cmderr_if_set();
257	    request_resume();
258	    poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
259	                   "ResumeDriver resume");
260	  }
261	
262	private:
263	  void request_halt()
264	  {
265	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolHaltreq);
266	  }
267	
268	  void request_resume()
269	  {
270	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolResumereq);
271	  }
272	
273	  void write_64bit_register(uint16_t regno, uint64_t value)
274	  {
275	    write_register_abstract(bus_, regno, value);
276	  }
277	
278	  // Abstract-first CSR write with Program Buffer fallback.
279	  // Tries an abstract register write; if the DM signals cmderr, clears it,
280	  // stages the value in scratch_gpr via abstract GPR write, then executes a
281	  // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
282	  // to x5 (t0) which the GPR restore loop overwrites later.
283	  void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
284	                                 uint8_t scratch_gpr = 5)
285	  {
286	    write_64bit_register(regno_csr(csr), value);
287	    if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
288	    bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
289	    write_64bit_register(regno_gpr(scratch_gpr), value);
290	    const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
291	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
292	  }
293	
294	  // Write a CSR-addressable register and clear any cmderr the DM raised.
295	  // Used for CSRs whose abstract-access support may be implementation
296	  // dependent; a missing CSR mirrors as a no-op rather than blocking the
297	  // remaining writes.
298	  void write_csr_tolerant(uint16_t csr, uint64_t value)
299	  {
300	    write_64bit_register(regno_csr(csr), value);
301	    clear_cmderr_if_set();
302	  }
303	
304	  // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
305	  // is rejected until the bits are W1C-cleared. We tolerate per-register
306	  // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
307	  // error before resuming so the hart isn't left in a stuck state.
308	  // B17: record the last observed non-zero cmderr and a clear count so a
309	  // partially-broken restore is observable via the public accessors
310	  // instead of silently swallowed.
311	  void clear_cmderr_if_set()
312	  {
313	    const auto status = bus_.read(kAbstractcs);
314	    const auto code = (status & kAbstractcsCmderrMask) >> 8;
315	    if (code != 0u) {
316	      last_observed_cmderr_ = code;
317	      ++cmderr_clear_count_;
318	      bus_.write(kAbstractcs, kAbstractcsCmderrMask);
319	    }
320	  }
321	
322	  DmiBus& bus_;
323	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
324	  uint32_t last_observed_cmderr_ = 0;
325	  uint64_t cmderr_clear_count_   = 0;
326	
327	public:
328	  // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
329	  // at least one abstract write tripped a sticky cmderr the restore
330	  // tolerated by clearing. cmderr_clear_count() is the total number of
331	  // such clears across all calls into clear_cmderr_if_set() this run.
332	  auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
333	  auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
334	};
335	
336	// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
337	// via an Abstract Command. Halts-and-reads contract: caller must have the
338	// hart in the halted state. Shared by StateDrain (drain at exit), and by
339	// MeasureStartSnapshot (snapshot at K-th retire). If abstractcs.cmderr
340	// goes sticky after the command, the helper clears it and reports 0
341	// rather than blocking the caller -- a missing CSR mirrors as zero
342	// instead of corrupting the adjacent field.
343	inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
344	                                     const char* poll_label
345	                                       = "read_register_64")
346	  -> std::optional<uint64_t>
347	{
348	  using RD = ResumeDriver;
349	  bus.write(RD::kCommand,
350	            access_register_command(regno, AarSize::Bits64, /*write=*/false));
351	  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
352	  const auto status = bus.read(RD::kAbstractcs);
353	  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
354	    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
355	    return std::nullopt;
356	  }
357	  const uint64_t lo = bus.read(RD::kData0);
358	  const uint64_t hi = bus.read(RD::kData1);
359	  return lo | (hi << 32);
360	}
361	
362	inline auto read_register_64(DmiBus& bus, uint16_t regno,
363	                             const char* poll_label = "read_register_64")
364	  -> uint64_t
365	{
366	  return read_register_64_checked(bus, regno, poll_label).value_or(0u);
367	}
368	
369	}  // namespace hybrid
370

  // access faults (priv spec v1.10) -- mirror the producer's PMP block
  // so the ROI can fetch at all. All pmpaddr before any pmpcfg (a locked
  // cfg discards later addr writes); odd pmpcfg CSRs do not exist on
  // RV64. Tolerant writes: entries beyond what the hart implements
  // mirror as no-ops. M-mode handoffs keep PMP pass-through-only (L2).
  for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
    write_csr_tolerant(kCsrPmpaddr0 + i, state.pmpaddr[i]);
  for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
    write_csr_tolerant(kCsrPmpcfg0 + i, state.pmpcfg[i]);

  const uint64_t dcsr =
    read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr");
  write_csr_abstract_or_pb(kCsrDcsr,
                           (dcsr & ~uint64_t{0x3}) | state.priv);
}

// GPRs + DPC (after V CSRs so PB scratch x5 is safe to overwrite).
for (uint16_t i = 1; i < 32; ++i)
  write_64bit_register(regno_gpr(i), state.gpr[i]);
write_64bit_register(regno_csr(kCsrDpc), state.pc);

commit 20138a7301e0526186ca1d48c8f3d2959659b99c
Author: Nick Hung <nick@andestech.com>
Date:   Tue Jun 16 16:25:44 2026 +0800

    behavioral: restore Andes mcache_ctl/mmisc_ctl on hybrid resume (L21)

    crt0 enables the L1 I/D caches via `csrw mcache_ctl,0x703` at boot, but
    that write runs on the functional engine, which has no cache model.
    Without restoring the CSR, the cycle engine resumed at the ROI with
    caches at their reset default -- disabled -- so the whole measured
    window ran uncached, inflating it ~5x (hello main->_exit: 14707 -> 2871).

    ResumeDriver now restores mcache_ctl (0x7CA) and mmisc_ctl (0x7D0) via
    the existing write_csr_tolerant path, alongside the L24 trap CSRs. An
    engine without these custom CSRs (e.g. non-Andes) no-ops the write.

    Tests: new resume_driver case asserts both CSR write-COMMANDs carry the
    drained value on DATA0/DATA1; state_abi.test.cpp locks the new field
    offsets.

    Co-Authored-By: Claude Opus 4.8 (1M context) <noreply@anthropic.com>

